    schemas = createTransactionSchemaHttp(scope, contracts, service.schemaObserved);
    handler = createTransactionHttpHandler(service, scope, capturedSeams.maximumOperations);
  } catch (error) {
    const failures: unknown[] = [error];
    if (server.listening)
