107	  let configurationMetadata: ReturnType<typeof captured.metadata>;
108	  let listenUrl = "";
109	  let scope = "",
110	    closing = false;
111	  const pending = new Set<Promise<void>>();
112	  // Retain only the first unexpected live fault. Wire cancellation remains
113	  // silent; close surfaces the original cause through existing aggregation.
114	  let firstStreamFault: { readonly cause: unknown } | undefined;
115	  const handle = async (request: IncomingMessage, response: ServerResponse): Promise<void> => {
116	    let signal: AbortSignal | undefined;
