217	        },
218	      ],
219	    });
220	    expect(receipt.results).toHaveLength(1);
221	    const after = await exchange("beads/a", "GET", true, 200),
222	      value = JSON.parse(after.bodyText);
223	    expect(beadSchema(value), JSON.stringify(beadSchema.errors)).toBe(true);
224	    expect(value).toMatchObject({ id: `${scope}beads/a`, type: bead, properties: { n: 1 } });
