264	      observation: "private-installed-discovery-boundary",
265	      declaredSourceCommit: source,
266	      workspaceDirty,
267	      entry,
268	      entrySha256: hash(readFileSync(entry)),
269	      binding,
270	      session,
271	      exchanges: observations.length,
272	      completedResponses: observations,
273	      outcome: failures.length ? "failed" : "passed",
274	      claimEligible: false,
275	    };
276	    const serialized = JSON.stringify(report);
277	    if (serialized.includes(token)) failures.push(new Error("unsafe observation report"));
278	    else console.log(serialized);
279	  }
280	  if (failures.length === 1) throw failures[0];
281	  if (failures.length)
282	    throw new AggregateError(failures, "installed discovery boundary or cleanup failed");
283	}, 60000);
